package com.newoether.agora.api.openai

import com.newoether.agora.api.GenerationError
import com.newoether.agora.api.StreamEvent
import com.newoether.agora.model.TokenUsage
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Decodes the committed codec fixtures (generated by
 * core/tools/golden/openai/codec/generate_codec_fixtures.py and byte-compared by
 * core/tests/openai_stream_codec_test.cpp) back into events. Together the two tests pin both
 * ends of the wire format documented in core/include/agora/core/openai_stream_codec.hpp.
 */
class NativeStreamCodecTest {

    private fun fixture(name: String): ByteArray = checkNotNull(
        javaClass.getResourceAsStream("/openai_stream_codec/$name"),
    ) { "missing codec fixture $name" }.use { it.readBytes() }

    @Test
    fun lineOutcomeFixtureDecodesToThePinnedEvents() {
        val outcome = NativeStreamCodec.decodeLineOutcome(fixture("line_outcome.bin"))

        assertTrue(outcome.keepReading)
        assertEquals(
            listOf("[agora] malformed stream payload exception=JsonDecodingException"),
            outcome.logs,
        )
        assertEquals(8, outcome.events.size)

        assertEquals(StreamEvent.TextChunk("Привет 😀\n\t"), outcome.events[0])
        assertEquals(StreamEvent.ThoughtChunk(thought = "думаю"), outcome.events[1])
        assertEquals(
            StreamEvent.ToolCallUpdate(
                streamKey = "call_stream_00000000-0000-4000-8000-000000000001",
                id = null,
                name = "",
                arguments = "{}",
            ),
            outcome.events[2],
        )
        assertEquals(
            StreamEvent.ToolCallUpdate(
                streamKey = "call_stream_00000000-0000-4000-8000-000000000002",
                id = "call_ab",
                name = "search",
                arguments = "{\"q\":\"x\"}",
            ),
            outcome.events[3],
        )
        assertEquals(
            StreamEvent.ToolCallRequest(
                id = "call_ab",
                name = "search",
                arguments = "{\"q\":\"x\"}",
                streamKey = "call_ab",
            ),
            outcome.events[4],
        )
        assertEquals(
            listOf(
                StreamEvent.ToolCallRequest(
                    id = "c1",
                    name = "n1",
                    arguments = "{}",
                    streamKey = "c1",
                ),
                StreamEvent.ToolCallRequest(
                    id = "c2",
                    name = "n2",
                    arguments = "[]",
                    signature = "sig2",
                    streamKey = "c2",
                ),
            ),
            (outcome.events[5] as StreamEvent.ToolCallsRequest).calls,
        )
        assertEquals(
            StreamEvent.UsageUpdate(
                TokenUsage(
                    totalTokenCount = 100,
                    inputTokenCount = 10,
                    cacheWriteInputTokenCount = 5,
                    outputTokenCount = 20,
                ),
            ),
            outcome.events[6],
        )
        assertEquals(
            StreamEvent.Error(
                GenerationError.SseParse(rawLine = "raw|x", cause = "cause;text\nmore"),
            ),
            outcome.events[7],
        )
    }

    @Test
    fun terminationFixtureDecodesToThePinnedTermination() {
        val termination = NativeStreamCodec.decodeTermination(fixture("termination.bin"))

        assertFalse(termination.sawTerminalMarker)
        assertNull(termination.stopReason)
        assertTrue(termination.producedContent)
        assertTrue(termination.toolCallInFlight)
        assertTrue(termination.timedOut)
        assertFalse(termination.alreadyReportedError)
        assertTrue(termination.retryableStreamError)
        assertEquals(
            GenerationError.IncompleteStream(
                provider = "agora",
                stopReason = "length",
                toolCallInFlight = true,
                producedContent = true,
            ),
            termination.streamError,
        )
    }

    @Test
    fun aTruncatedPayloadFailsLoudly() {
        val bytes = fixture("termination.bin")
        val truncated = bytes.copyOf(bytes.size - 1)
        assertTrue(runCatching { NativeStreamCodec.decodeTermination(truncated) }.isFailure)
    }
}
